function guide(
  topic: EuropeGuideTopic,
  sourceIds: string[],
  copy: LocalCopy,
): EuropeCountryProfile["topics"][EuropeGuideTopic] {
  return {
    sourceIds,
    copy: Object.fromEntries(
      Object.entries(copy).map(([locale, text]) => [
        locale,
        `${text} ${DECISIONS[topic][locale as EuropeBlogLocale]}`,
      ]),
    ) as LocalCopy,
  };
}
function source(id: string, label: string, url: string) {
  return { id, label, url, checkedAt: CHECKED_AT };
}

